using System;using System.IO;using System.Linq;using System.Collections;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using UnityEngine.SceneManagement;using DeliveryService.Yun.Settings;
namespace DeliveryService.Mok.Editor {
[InitializeOnLoad]public static class LobbyCheck {
const string Key="Mok.Lobby.Check";static IEnumerator routine;static string log;static double began;static int frame=-1;
static LobbyCheck(){EditorApplication.update+=Poll;EditorApplication.playModeStateChanged+=Changed;}
static void Poll(){if(EditorApplication.isCompiling||EditorApplication.isUpdating||EditorApplication.isPlayingOrWillChangePlaymode)return;
 if(File.Exists("Temp/Mok-lobby-refine-request")){File.Delete("Temp/Mok-lobby-refine-request");var s=SceneManager.GetActiveScene();if(s.name!="Lobby")return;foreach(var n in UnityEngine.Object.FindObjectsByType<NPCControl>(FindObjectsInactive.Include,FindObjectsSortMode.None))UnityEngine.Object.DestroyImmediate(n);foreach(var a in UnityEngine.Object.FindObjectsByType<UnityEngine.AI.NavMeshAgent>(FindObjectsInactive.Include,FindObjectsSortMode.None))UnityEngine.Object.DestroyImmediate(a);foreach(var c in UnityEngine.Object.FindObjectsByType<Camera>(FindObjectsInactive.Include,FindObjectsSortMode.None))if(c.name!="Lobby Camera"){var d=c.GetComponent<UnityEngine.Rendering.Universal.UniversalAdditionalCameraData>();if(d)UnityEngine.Object.DestroyImmediate(d);UnityEngine.Object.DestroyImmediate(c);}EditorSceneManager.SaveScene(s);}
 if(!File.Exists("Temp/Mok-lobby-test-request"))return;File.Delete("Temp/Mok-lobby-test-request");Backup();SessionState.SetBool(Key,true);EditorApplication.EnterPlaymode();}
static void Backup(){var list=PlayerPrefs.GetString("PendingToppingList","");var names=AssetDatabase.FindAssets("t:PizzaToppingData").Select(g=>AssetDatabase.LoadAssetAtPath<PizzaToppingData>(AssetDatabase.GUIDToAssetPath(g)).toppingName).Concat(list.Split(',')).Where(n=>!string.IsNullOrEmpty(n)).Distinct();string economy=System.IO.Path.Combine(Application.persistentDataPath,"economySave.json");var b=new StockCheck.Backup{values=names.SelectMany(n=>new[]{"Stock_"+n,"Pending_"+n}).Select(k=>new StockCheck.SavedKey{key=k,exists=PlayerPrefs.HasKey(k),value=PlayerPrefs.GetInt(k)}).ToArray(),listExists=PlayerPrefs.HasKey("PendingToppingList"),list=list,economyPath=economy,economyExists=File.Exists(economy),economy=File.Exists(economy)?File.ReadAllText(economy):null};File.WriteAllText("Temp/Mok-lobby-save-backup.json",JsonUtility.ToJson(b));SessionState.SetFloat(Key+".bgm",PlayerPrefs.GetFloat("Yun.Settings.BgmVolume",1));SessionState.SetFloat(Key+".sfx",PlayerPrefs.GetFloat("Yun.Settings.SfxVolume",1));SessionState.SetBool(Key+".hadbgm",PlayerPrefs.HasKey("Yun.Settings.BgmVolume"));SessionState.SetBool(Key+".hadsfx",PlayerPrefs.HasKey("Yun.Settings.SfxVolume"));}
static void Changed(PlayModeStateChange s){if(!SessionState.GetBool(Key,false))return;if(s==PlayModeStateChange.EnteredPlayMode){began=EditorApplication.timeSinceStartup;routine=Run();log="Lobby verification\n";frame=-1;SessionState.SetBool(Key+".background",Application.runInBackground);Application.runInBackground=true;EditorApplication.update+=Tick;}if(s==PlayModeStateChange.EnteredEditMode)EditorApplication.delayCall+=Restore;}
static void Tick(){if(!EditorApplication.isPlaying||Time.frameCount<4||frame==Time.frameCount)return;frame=Time.frameCount;try{if(EditorApplication.timeSinceStartup-began>150)throw new Exception("timeout");if(routine.MoveNext())return;}catch(Exception e){log+="FAIL: "+e+"\n";}EditorApplication.update-=Tick;File.WriteAllText("Temp/Mok-lobby-check.txt",log);EditorApplication.ExitPlaymode();}
static void Check(bool pass,string message){if(!pass)throw new Exception(message);log+="PASS: "+message+"\n";}
static IEnumerator Run(){
 var c=UnityEngine.Object.FindFirstObjectByType<LobbyController>();Check(c!=null,"별도 로비 씬 및 컨트롤러");Check(UnityEngine.Object.FindFirstObjectByType<DayNightCycle>()==null&&UnityEngine.Object.FindFirstObjectByType<OrderManager>()==null&&UnityEngine.Object.FindFirstObjectByType<NPCControl>()==null,"게임 시간·주문·시민 전투 AI 없음");Check(Camera.allCamerasCount==1,"로비 카메라 한 대");
 float until=Time.realtimeSinceStartup+2;while(Time.realtimeSinceStartup<until)yield return null;
 ScreenCapture.CaptureScreenshot("Temp/Mok-lobby-main.png",2);yield return null;
 var w=UnityEngine.Object.FindObjectsByType<LobbyWalker>(FindObjectsSortMode.None).First(x=>x.delay==0);var old=w.transform.position;until=Time.realtimeSinceStartup+1;while(Time.realtimeSinceStartup<until)yield return null;Check(Vector3.Distance(old,w.transform.position)>.5f,"시민 배경 이동");Check(w.GetComponentInChildren<Animator>().GetBool("IsWalking"),"시민 걷기 애니메이션");
 c.settingsButton.onClick.Invoke();yield return null;Check(c.settingsPanel.activeSelf&&!c.menu.interactable,"설정 열기 및 배경 메뉴 입력 차단");c.bgm.value=.3f;c.sfx.value=.6f;Check(Mathf.Approximately(c.audioSettings.BgmVolume,.3f)&&Mathf.Approximately(c.audioSettings.SfxVolume,.6f),"배경음·효과음 기존 설정 연동");ScreenCapture.CaptureScreenshot("Temp/Mok-lobby-settings.png",2);yield return null;c.backButton.onClick.Invoke();Check(!c.settingsPanel.activeSelf&&c.menu.interactable,"설정 닫기");
 c.startButton.onClick.Invoke();c.startButton.onClick.Invoke();Check(c.IsLoading,"게임 시작 및 중복 입력 차단");while(SceneManager.GetActiveScene().name!="JJinCity")yield return null;yield return null;yield return null;
 Check(UnityEngine.Object.FindFirstObjectByType<DayNightCycle>()!=null&&MoneyManager.Instance.currentMoney==20000,"게임 씬 로드 및 초기 자금 20000원");Check(UnityEngine.Object.FindFirstObjectByType<LobbyController>()==null,"로비 씬 제거");var p=UnityEngine.Object.FindFirstObjectByType<GameSettingsPanel>(FindObjectsInactive.Include);Check(p!=null,"게임 설정 존재");p.gameObject.SetActive(true);yield return null;p.ReturnToLobby();while(SceneManager.GetActiveScene().name!="Lobby")yield return null;yield return null;yield return null;Check(Time.timeScale==1,"게임 설정에서 로비 복귀 및 시간 복구");
 c=UnityEngine.Object.FindFirstObjectByType<LobbyController>();MoneyManager.Instance.currentMoney=123;c.startButton.onClick.Invoke();while(SceneManager.GetActiveScene().name!="JJinCity")yield return null;yield return null;yield return null;Check(MoneyManager.Instance.currentMoney==20000,"재시작 자금 초기화");Check(UnityEngine.Object.FindFirstObjectByType<DayNightCycle>().currentDay==1,"재시작 첫날 초기화");
 p=UnityEngine.Object.FindFirstObjectByType<GameSettingsPanel>(FindObjectsInactive.Include);p.gameObject.SetActive(true);yield return null;p.ReturnToLobby();while(SceneManager.GetActiveScene().name!="Lobby")yield return null;yield return null;
 Check(UnityEngine.Object.FindFirstObjectByType<LobbyController>().quitButton!=null,"종료 버튼 연결");File.WriteAllText("Temp/Mok-lobby-check.txt",log+"PASS: 종료 버튼 호출 (에디터 Play 종료)\n");EditorApplication.update-=Tick;UnityEngine.Object.FindFirstObjectByType<LobbyController>().quitButton.onClick.Invoke();yield return null;
}
static void Restore(){try{var b=JsonUtility.FromJson<StockCheck.Backup>(File.ReadAllText("Temp/Mok-lobby-save-backup.json"));foreach(var k in b.values){if(k.exists)PlayerPrefs.SetInt(k.key,k.value);else PlayerPrefs.DeleteKey(k.key);}if(b.listExists)PlayerPrefs.SetString("PendingToppingList",b.list);else PlayerPrefs.DeleteKey("PendingToppingList");foreach(var pair in new[]{new[]{".bgm","Yun.Settings.BgmVolume",".hadbgm"},new[]{".sfx","Yun.Settings.SfxVolume",".hadsfx"}}){if(SessionState.GetBool(Key+pair[2],false))PlayerPrefs.SetFloat(pair[1],SessionState.GetFloat(Key+pair[0],1));else PlayerPrefs.DeleteKey(pair[1]);}PlayerPrefs.Save();if(b.economyExists)File.WriteAllText(b.economyPath,b.economy);else if(File.Exists(b.economyPath))File.Delete(b.economyPath);File.AppendAllText("Temp/Mok-lobby-check.txt","Original inventory, economy and audio preferences restored.\n");}finally{Application.runInBackground=SessionState.GetBool(Key+".background",false);SessionState.SetBool(Key,false);EditorApplication.update-=Tick;Cursor.lockState=CursorLockMode.None;Cursor.visible=true;}}
}
